CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE places(id text PRIMARY KEY,name text NOT NULL,description text,latitude numeric NOT NULL,longitude numeric NOT NULL,category text NOT NULL,tags text[] DEFAULT '{}',average_cost integer DEFAULT 0,rating numeric,visit_duration_minutes integer,opening_time time,closing_time time,indoor_outdoor text,weather_sensitivity text,popularity_score integer,friends_friendly boolean,family_friendly boolean,solo_friendly boolean,active boolean DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE trips(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),destination text,budget integer,currency text DEFAULT 'INR',status text DEFAULT 'planned',requirements jsonb,score integer,started_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE trip_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES trips(id) ON DELETE CASCADE,place_id text REFERENCES places(id),position integer,start_time timestamptz,end_time timestamptz,cost integer,status text DEFAULT 'planned',recommendation_score integer,metadata jsonb,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE trip_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES trips(id) ON DELETE CASCADE,event_type text NOT NULL,data jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE trip_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES trips(id) ON DELETE CASCADE,revision_number integer,items jsonb,changes jsonb,explanation text,created_at timestamptz DEFAULT now());
CREATE TABLE user_preferences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),preference_type text,value text,weight numeric DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE recommendation_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES trips(id),place_id text REFERENCES places(id),scores jsonb,final_score numeric,reasons jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,name text NOT NULL UNIQUE,created_at timestamptz DEFAULT now());
CREATE TABLE relationships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_entity_id uuid REFERENCES entities(id),relationship_type text NOT NULL,target_entity_id uuid REFERENCES entities(id),weight numeric DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE custom_places(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),trip_id uuid REFERENCES trips(id) ON DELETE CASCADE,name text NOT NULL,display_name text,latitude numeric NOT NULL,longitude numeric NOT NULL,estimated_cost integer DEFAULT 0,visit_duration_minutes integer DEFAULT 60,user_priority text DEFAULT 'USER_MUST_VISIT',source text CHECK(source IN ('NOMINATIM','USER','DEMO')),created_at timestamptz DEFAULT now());
ALTER TABLE trip_items ADD COLUMN priority_type text DEFAULT 'AI_RECOMMENDED';
ALTER TABLE trip_items ADD COLUMN priority_score integer DEFAULT 50;
